  exportToExcel11() {
    const header = ['Date', 'Remarks', 'Referral']; // Add more headers if needed
  
    const data = this.getdatafollow.map(item => [
      item.Date,
      item.Remarks,
      item.Referral
    ]);
  
    const ws: XLSX.WorkSheet = XLSX.utils.aoa_to_sheet([header, ...data]);
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Sheet1');
  
    // Save the Excel file
    XLSX.writeFile(wb, 'exported_data.xlsx');
  }
  

  
  exportToExcel1() {
    let excelData = [];
    this.getdatafollow.map(item => {
      var obj = {
        'DATE': item.Date,
        'REMARKS': item.Remarks,
        'REFERRAL': item.Referral,
      };
      excelData.push(obj);
    });
    return excelData;
  }

